module.exports = {
    onConnect: function(transport, config) {
        engine.setStatus('connecting', 'Starting UDP...');
    },
    onTransportReady: function(transport, config) {
        engine.setStatus('connected', 'Ready');
    },
    onAction: function(transport, actionId, params) {
        if (actionId === 'send_command') {
            var op = parseInt(params.command_id, 10) || 1;
            // Header 0xAA 0x55, Opcode, Length 0x00, Checksum
            var payload = [0xAA, 0x55, op & 0xFF, 0x00];
            var csum = engine.checksum.sum8(payload);
            payload.push(csum);
            transport.sendBytes(payload);
            return 'Sent binary command ' + op;
        }
        return 'Unknown action';
    },
    onMessage: function(transport, text, bytes) {
        if (bytes.length >= 4 && bytes[0] === 0xAA && bytes[1] === 0x55) {
            var statusByte = bytes[2];
            engine.setVariable('tally_program', (statusByte & 0x01) ? 'true' : 'false');
        }
    }
};
